-- Idempotent install for rootcause.resolution_paths
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS rootcause;

CREATE SEQUENCE IF NOT EXISTS rootcause.resolution_paths_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS rootcause.resolution_paths (
    id integer NOT NULL,
    root_cause_id character varying(40) NOT NULL,
    vendor_slug character varying(50) NOT NULL,
    name character varying(300) NOT NULL,
    slug character varying(300) NOT NULL,
    description text,
    execution_mode character varying(50) DEFAULT 'supervised'::character varying NOT NULL,
    risk_level character varying(20),
    risk_description text,
    status character varying(50) DEFAULT 'authored'::character varying NOT NULL,
    prerequisites jsonb,
    is_active boolean DEFAULT true NOT NULL,
    min_version character varying(20),
    max_version character varying(20),
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL
);

ALTER TABLE rootcause.resolution_paths ALTER COLUMN id SET DEFAULT nextval('rootcause.resolution_paths_id_seq'::regclass);
ALTER SEQUENCE rootcause.resolution_paths_id_seq OWNED BY rootcause.resolution_paths.id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE rootcause.resolution_paths);
SELECT id, root_cause_id, vendor_slug, name, slug, description, execution_mode, risk_level, risk_description, status, prerequisites, is_active, min_version, max_version, created_at, updated_at FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM rootcause.resolution_paths);
DROP TABLE _stg_load;

SELECT setval('rootcause.resolution_paths_id_seq', GREATEST((SELECT COALESCE(max(id),0) FROM rootcause.resolution_paths),1), (SELECT count(*) FROM rootcause.resolution_paths) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'rootcause' AND c.relname = 'resolution_paths'
          AND con.conname = 'resolution_paths_pkey') THEN
        ALTER TABLE ONLY rootcause.resolution_paths
    ADD CONSTRAINT resolution_paths_pkey PRIMARY KEY (id);
    END IF;
END $do$;
DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'rootcause' AND c.relname = 'resolution_paths'
          AND con.conname = 'uq_rp_rc_vendor_name') THEN
        ALTER TABLE ONLY rootcause.resolution_paths
    ADD CONSTRAINT uq_rp_rc_vendor_name UNIQUE (root_cause_id, vendor_slug, name);
    END IF;
END $do$;

CREATE INDEX IF NOT EXISTS ix_resolution_paths_root_cause_id ON rootcause.resolution_paths USING btree (root_cause_id);
CREATE INDEX IF NOT EXISTS ix_resolution_paths_vendor_slug ON rootcause.resolution_paths USING btree (vendor_slug);
